def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = []
    weak_prev = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= 100:
                    strong_prev.append(float(bid))
                else:
                    weak_prev.append(float(bid))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.2))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.7
    elif hp <= 4:
        urgency += 0.4
    if no_water_days >= 2:
        urgency += 0.6
    elif no_water_days == 1:
        urgency += 0.25
    urgency += 0.35 * scarcity
    if day >= 8:
        urgency += 0.1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strong_high = max(strong_prev) if strong_prev else highest_prev

    affordable_cap = min(budget, max(0.0, budget * 0.42 + DAILY_SALARY * 0.35))

    if urgency >= 1.0:
        target = max(DAILY_SALARY * 0.95, strong_high + 2.0)
    elif urgency >= 0.6:
        target = max(DAILY_SALARY * 0.68, strong_high * 0.78 + 3.0)
    elif scarcity >= 0.7:
        target = max(DAILY_SALARY * 0.52, strong_high * 0.55)
    else:
        target = DAILY_SALARY * 0.28
        if highest_prev > 0 and highest_prev < 80:
            target = max(target, highest_prev + 1.0)

    rich_alive = 0
    for opp in alive:
        if opp.get('budget', 0) >= 500:
            rich_alive += 1
    if rich_alive >= 2 and urgency < 0.8:
        target *= 0.9

    if budget <= DAILY_SALARY * 1.2:
        target = min(target, budget * 0.75)

    bid = min(affordable_cap, target)
    if hp > 6 and no_water_days == 0 and scarcity <= 0.2:
        bid = min(bid, DAILY_SALARY * 0.22)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    # Emergency bid if HP is critically low
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                yesterday_bids.append(prev_trace['bid'])

    # Determine target bid
    # Base bid, competitive with successful opponents like Alex and Eric
    base_competitive_bid = DAILY_SALARY * 0.77  # ~115.5

    target_bid = base_competitive_bid

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        # If opponents bid high, ensure we outbid them with a small buffer
        # Otherwise, maintain a competitive bid but don't overspend unnecessarily
        if max_prev_bid >= DAILY_SALARY * 0.7:
            target_bid = max_prev_bid + 5.0
        else:
            target_bid = max(base_competitive_bid, max_prev_bid + 1.0)

    # Adjust bid for budget constraint
    final_bid = min(my_status['budget'], target_bid)

    # Ensure bid is not negative or zero if budget is very low
    return max(0.0, final_bid)

